import type { AdNetworkAdapter } from "./registry.js"; import { escapeHtml, safeUrl, sanitizeHtml } from "./safe.js";
export const directSponsorAdapter: AdNetworkAdapter={id:"direct-sponsor",async mount(unit,container){ const w=unit.width?` width="${Number(unit.width)}"`:""; const h=unit.height?` height="${Number(unit.height)}"`:""; let body=unit.html?sanitizeHtml(String(unit.html)):""; if(!body && unit.image_url) body=`<img src="${escapeHtml(safeUrl(String(unit.image_url))!)}" alt="${escapeHtml(String(unit.alt_text??"Advertisement"))}"${w}${h}>`; if(!body) body=`<span>${escapeHtml(String(unit.text??"Sponsored"))}</span>`; if(unit.destination_url) body=`<a rel="sponsored noopener" ${unit.target_blank!==false?'target="_blank" ':""}href="${escapeHtml(safeUrl(String(unit.destination_url))!)}">${body}</a>`; container.innerHTML=`<div class="ad-runner-direct">${body}</div>`; return {outcome:"filled",renderedAt:Date.now()};},async destroy(_u,c){c.remove();}};
